#pragma once
#include "rinkfit/joint_builder.hpp"
namespace rinkfit {
struct JointNativeProbe {JointRowEvaluation row;template<class T>bool operator()(T const*const*p,T*r)const{Vec2<T>e;if(!row.native_error(p,&e))return false;r[0]=e[0];r[1]=e[1];return true;}};
inline eventio::Json verify_joint_kernel(JointProblemBuilder&b){eventio::Json results;double worst=0;std::size_t checks=0;for(std::size_t i=0;i<b.packet.rows.size();++i){const auto&o=b.packet.rows[i];if(!o.active)continue;auto q=b.row_evaluation(i);std::set<int>unique(q.layout.block_ids.begin(),q.layout.block_ids.end());if(unique.size()!=q.layout.block_ids.size())throw std::runtime_error("duplicated physical parameter pointer");auto ptr=b.model.pointers(q.layout);std::vector<int>sizes;for(auto id:q.layout.block_ids)sizes.push_back(int(b.model.blocks[id].values.size()));ceres::DynamicAutoDiffCostFunction<JointNativeProbe,4>cost(new JointNativeProbe{q});for(auto n:sizes)cost.AddParameterBlock(n);cost.SetNumResiduals(2);std::vector<std::vector<double>>jac;std::vector<double*>jp;for(auto n:sizes){jac.emplace_back(2*n);jp.push_back(jac.back().data());}double e[2];if(!cost.Evaluate(ptr.data(),e,jp.data()))throw std::runtime_error("AD native evaluation failed");std::vector<std::pair<int,int>>coords={{q.layout.scene_slot,0},{q.layout.rig_slot,6},{q.layout.optics_slot,0},{q.layout.reference_angles_slot,0},{q.layout.control_slots.at(1),2}};eventio::Json rowres;for(auto sc:coords){int slot=sc.first,c=sc.second;int id=q.layout.block_ids[slot];auto&v=b.model.blocks[id].values[c];double before=v,h=c==0&&slot==q.layout.optics_slot?1e-4:1e-7;v=before+h;Vec2<double>plus;if(!q.native_error(ptr.data(),&plus))throw std::runtime_error("positive finite difference invalid");v=before-h;Vec2<double>minus;if(!q.native_error(ptr.data(),&minus))throw std::runtime_error("negative finite difference invalid");v=before;double err=0;for(int a=0;a<2;++a){double fd=(plus[a]-minus[a])/(2*h),ad=jac[slot][a*sizes[slot]+c];err=std::max(err,std::abs(fd-ad)/(1+std::abs(fd)));}if(err>2e-5)throw std::runtime_error("joint AD finite difference mismatch");worst=std::max(worst,err);++checks;rowres.push_back({{"block",b.model.blocks[id].name},{"component",c},{"normalized_AD_FD_error",err}});}results[o.shot_id]=rowres;}
// Correlated W derivative and coupled nuisance Hessian use exact group member union.
const auto&g=b.packet.groups.front();JointGroupedStatistic f;f.group=&g;std::vector<int>ids;std::vector<double*>ptr;std::vector<int>sizes;for(auto i:g.rows){auto q=b.row_evaluation(i);for(auto id:q.layout.block_ids)if(std::find(ids.begin(),ids.end(),id)==ids.end())ids.push_back(id);f.rows.push_back(q);}for(auto id:ids){ptr.push_back(b.model.blocks[id].values.data());sizes.push_back(int(b.model.blocks[id].values.size()));}for(std::size_t k=0;k<f.rows.size();++k){auto&q=f.rows[k];std::vector<int>map;for(auto id:q.layout.block_ids)map.push_back(int(std::find(ids.begin(),ids.end(),id)-ids.begin()));q=q.remap(map);q.station_slot=int(ptr.size());ptr.push_back(&b.station[g.rows[k]]);sizes.push_back(1);}ceres::DynamicAutoDiffCostFunction<JointGroupedStatistic,4>cost(new JointGroupedStatistic(f));for(auto n:sizes)cost.AddParameterBlock(n);cost.SetNumResiduals(int(g.rank));std::vector<std::vector<double>>jac;std::vector<double*>jp;for(auto n:sizes){jac.emplace_back(g.rank*n);jp.push_back(jac.back().data());}std::vector<double>r(g.rank);if(!cost.Evaluate(ptr.data(),r.data(),jp.data()))throw std::runtime_error("full W AD failed");double manual=0,computed=0;std::vector<double>native;for(auto i:g.rows){auto q=b.row_evaluation(i);auto p=b.model.pointers(q.layout);Vec2<double>e;if(!q.native_error(p.data(),&e))throw std::runtime_error("native W fixture failure");native.push_back(e[0]);native.push_back(e[1]);}for(std::size_t a=0;a<g.rank;++a){double w=0;for(std::size_t z=0;z<native.size();++z)w+=g.W[a*native.size()+z]*native[z];manual+=.5*w*w;computed+=.5*r[a]*r[a];}if(std::abs(manual-computed)>1e-10*(1+manual))throw std::runtime_error("full W cost mismatch");double cross=0;auto a=jac.size()-g.rows.size();if(g.rows.size()>1)for(std::size_t k=0;k<g.rank;++k)cross+=jac[a][k]*jac[a+1][k];
return {{"schema","rinkfit.joint_kernel_minimal_verification.v1"},{"AD_FD_checks",checks},{"max_normalized_AD_FD_error",worst},{"per_shot_dependencies",results},{"group_half_cost",computed},{"independent_full_W_half_cost",manual},{"correlated_station_Hessian_off_diagonal",cross},{"independent_station_Schur_assumption_valid",cross==0},{"whole_RS_certificate_proven",false},{"fixture_not_calibration",true}};}
}
